import { useState } from "react";
import { usePanier } from "../hooks/usePanier";
import { useAuth } from "../hooks/useAuth";
import { ajouterCommande } from "../services/serviceCommandes";
import { useNavigate, Link } from "react-router-dom";

const couleur = "#3B5BDB";

const MODES_PAIEMENT = [
  {
    id: "visa",
    label: "Carte Visa / Mastercard",
    image: "https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=80&q=80",
    description: "Paiement sécurisé par carte bancaire",
  },
  {
    id: "paypal",
    label: "PayPal",
    image: "https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=80&q=80",
    description: "Payer via votre compte PayPal",
  },
  {
    id: "virement",
    label: "Virement bancaire",
    image: "https://images.unsplash.com/photo-1601597111158-2fceff292cdc?w=80&q=80",
    description: "Virement direct depuis votre banque",
  },
  {
    id: "livraison",
    label: "Paiement à la livraison",
    image: "https://images.unsplash.com/photo-1526367790999-0150786686a2?w=80&q=80",
    description: "Payer en cash à la réception",
  },
];

export default function Panier() {
  const { panier, retirerDuPanier, viderPanier, totalPrix } = usePanier();
  const { utilisateur } = useAuth();
  const navigate = useNavigate();

  const [modePaiement, setModePaiement] = useState("visa");
  const [commande, setCommande] = useState(false);
  const [adresse, setAdresse] = useState({
    prenom: utilisateur?.nom || "",
    email: utilisateur?.email || "",
    telephone: "",
    adresse: "",
    ville: "",
    pays: "Maroc",
  });

  const fraisLivraison = totalPrix >= 500 ? 0 : 29.99;
  const totalFinal = totalPrix + fraisLivraison;

  const confirmerCommande = () => {
    ajouterCommande({ articles: panier, total: totalFinal, adresse, modePaiement });
    viderPanier();
    setCommande(true);
  };

  // ── COMMANDE CONFIRMÉE ──
  if (commande) {
    return (
      <div style={{ maxWidth: "500px", margin: "60px auto", textAlign: "center", padding: "40px", background: "white", borderRadius: "16px", border: "0.5px solid #e9ecef" }}>
        <div style={{ width: "80px", height: "80px", background: "#E6FCF5", borderRadius: "50%", overflow: "hidden", margin: "0 auto 20px" }}>
          <img
            src="https://images.unsplash.com/photo-1518458028785-8fbcd101ebb9?w=80&q=80"
            alt="succès"
            style={{ width: "100%", height: "100%", objectFit: "cover" }}
          />
        </div>
        <h2 style={{ fontSize: "22px", fontWeight: 700, color: "#212529", marginBottom: "10px" }}>
          Commande confirmée !
        </h2>
        <p style={{ color: "#868E96", fontSize: "14px", marginBottom: "28px" }}>
          Merci {adresse.prenom} ! Votre commande a été passée avec succès.
        </p>
        <div style={{ background: "#EEF2FF", borderRadius: "10px", padding: "16px", marginBottom: "24px" }}>
          <p style={{ fontSize: "13px", color: "#495057", marginBottom: "4px" }}>Total payé</p>
          <p style={{ fontSize: "28px", fontWeight: 700, color: couleur }}>{totalFinal.toFixed(2)} €</p>
        </div>
        <div style={{ display: "flex", gap: "12px", justifyContent: "center" }}>
          <button
            onClick={() => navigate("/mes-commandes")}
            style={{ background: couleur, color: "white", border: "none", padding: "12px 24px", borderRadius: "8px", cursor: "pointer", fontWeight: 600, fontSize: "14px", fontFamily: "inherit" }}
          >
            Voir mes commandes
          </button>
          <button
            onClick={() => navigate("/")}
            style={{ background: "#EEF2FF", color: couleur, border: "none", padding: "12px 24px", borderRadius: "8px", cursor: "pointer", fontWeight: 600, fontSize: "14px", fontFamily: "inherit" }}
          >
            Retour accueil
          </button>
        </div>
      </div>
    );
  }

  // ── PANIER VIDE ──
  if (panier.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "80px 20px" }}>
        <div style={{ width: "160px", height: "160px", borderRadius: "50%", overflow: "hidden", margin: "0 auto 24px" }}>
          <img
            src="https://images.unsplash.com/photo-1580902394724-b08ff42e0a58?w=200&q=80"
            alt="panier vide"
            style={{ width: "100%", height: "100%", objectFit: "cover", opacity: 0.6 }}
          />
        </div>
        <h2 style={{ fontSize: "20px", fontWeight: 700, color: "#212529", marginBottom: "10px" }}>
          Votre panier est vide
        </h2>
        <p style={{ color: "#868E96", fontSize: "14px", marginBottom: "24px" }}>
          Ajoutez des produits pour commencer vos achats
        </p>
        <Link to="/catalogue">
          <button style={{ background: couleur, color: "white", border: "none", padding: "12px 28px", borderRadius: "8px", cursor: "pointer", fontWeight: 600, fontSize: "14px", fontFamily: "inherit" }}>
            Voir le catalogue →
          </button>
        </Link>
      </div>
    );
  }

  return (
    <div>

      {/* ── HEADER ── */}
      <div style={{ background: `linear-gradient(135deg, ${couleur}, #4C6EF5)`, borderRadius: "14px", padding: "24px 32px", marginBottom: "28px" }}>
        <h1 style={{ color: "white", fontSize: "20px", fontWeight: 700, marginBottom: "4px" }}>Mon Panier</h1>
        <p style={{ color: "rgba(255,255,255,0.75)", fontSize: "13px" }}>{panier.length} article(s)</p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 380px", gap: "24px", alignItems: "start" }}>

        {/* ── COLONNE GAUCHE ── */}
        <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>

          {/* ARTICLES */}
          <div style={{ background: "white", borderRadius: "14px", border: "0.5px solid #e9ecef", overflow: "hidden" }}>
            <div style={{ padding: "16px 20px", borderBottom: "0.5px solid #e9ecef", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <h2 style={{ fontSize: "15px", fontWeight: 700, color: "#212529", margin: 0 }}>Articles</h2>
              <button
                onClick={viderPanier}
                style={{ background: "#FFF5F5", color: "#E03131", border: "none", padding: "6px 14px", borderRadius: "6px", cursor: "pointer", fontSize: "12px", fontWeight: 600, fontFamily: "inherit" }}
              >
                Vider le panier
              </button>
            </div>

            {panier.map((article, i) => (
              <div key={article.id} style={{ display: "flex", alignItems: "center", gap: "16px", padding: "16px 20px", borderBottom: i < panier.length - 1 ? "0.5px solid #f1f3f5" : "none" }}>
                <div style={{ width: "70px", height: "70px", background: "#f8f9fa", borderRadius: "10px", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <img src={article.image} alt={article.title} style={{ maxWidth: "60px", maxHeight: "60px", objectFit: "contain" }} />
                </div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontSize: "13px", fontWeight: 600, color: "#212529", marginBottom: "4px" }}>
                    {article.title?.slice(0, 45)}...
                  </p>
                  <span style={{ fontSize: "11px", background: "#EEF2FF", color: couleur, padding: "2px 8px", borderRadius: "20px", fontWeight: 600 }}>
                    {article.category}
                  </span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <span style={{ fontSize: "13px", color: "#868E96" }}>
                    {article.price} € × {article.quantite}
                  </span>
                  <span style={{ fontSize: "14px", fontWeight: 700, color: couleur, minWidth: "70px", textAlign: "right" }}>
                    {(article.price * article.quantite).toFixed(2)} €
                  </span>
                  <button
                    onClick={() => retirerDuPanier(article.id)}
                    style={{ background: "#FFF5F5", color: "#E03131", border: "none", width: "30px", height: "30px", borderRadius: "6px", cursor: "pointer", fontSize: "14px" }}
                  >
                    🗑
                  </button>
                </div>
              </div>
            ))}
          </div>

          {/* ADRESSE LIVRAISON */}
          <div style={{ background: "white", borderRadius: "14px", border: "0.5px solid #e9ecef", overflow: "hidden" }}>
            <div style={{ padding: "16px 20px", borderBottom: "0.5px solid #e9ecef", display: "flex", alignItems: "center", gap: "12px" }}>
              <img
                src="https://images.unsplash.com/photo-1566576721346-d4a3b4eaeb55?w=40&q=80"
                alt=""
                style={{ width: "36px", height: "36px", borderRadius: "8px", objectFit: "cover" }}
              />
              <h2 style={{ fontSize: "15px", fontWeight: 700, color: "#212529", margin: 0 }}>
                Adresse de livraison
              </h2>
            </div>
            <div style={{ padding: "20px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              {[
                { key: "prenom",    label: "Prénom",    placeholder: "Votre prénom" },
                { key: "email",     label: "Email",     placeholder: "votre@email.com" },
                { key: "telephone", label: "Téléphone", placeholder: "06 12 34 56 78" },
                { key: "ville",     label: "Ville",     placeholder: "Casablanca" },
              ].map(({ key, label, placeholder }) => (
                <div key={key}>
                  <label style={{ fontSize: "12px", fontWeight: 600, color: "#495057", display: "block", marginBottom: "6px" }}>
                    {label}
                  </label>
                  <input
                    value={adresse[key]}
                    onChange={(e) => setAdresse({ ...adresse, [key]: e.target.value })}
                    placeholder={placeholder}
                    style={{ width: "100%", padding: "9px 12px", borderRadius: "8px", border: "0.5px solid #dee2e6", fontSize: "13px", outline: "none", fontFamily: "inherit", boxSizing: "border-box" }}
                    onFocus={e => e.target.style.borderColor = couleur}
                    onBlur={e => e.target.style.borderColor = "#dee2e6"}
                  />
                </div>
              ))}
              <div style={{ gridColumn: "1 / -1" }}>
                <label style={{ fontSize: "12px", fontWeight: 600, color: "#495057", display: "block", marginBottom: "6px" }}>
                  Adresse complète
                </label>
                <input
                  value={adresse.adresse}
                  onChange={(e) => setAdresse({ ...adresse, adresse: e.target.value })}
                  placeholder="123 Rue Mohammed V"
                  style={{ width: "100%", padding: "9px 12px", borderRadius: "8px", border: "0.5px solid #dee2e6", fontSize: "13px", outline: "none", fontFamily: "inherit", boxSizing: "border-box" }}
                  onFocus={e => e.target.style.borderColor = couleur}
                  onBlur={e => e.target.style.borderColor = "#dee2e6"}
                />
              </div>
            </div>
          </div>

          {/* MODE DE PAIEMENT */}
          <div style={{ background: "white", borderRadius: "14px", border: "0.5px solid #e9ecef", overflow: "hidden" }}>
            <div style={{ padding: "16px 20px", borderBottom: "0.5px solid #e9ecef", display: "flex", alignItems: "center", gap: "12px" }}>
              <img
                src="https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=40&q=80"
                alt=""
                style={{ width: "36px", height: "36px", borderRadius: "8px", objectFit: "cover" }}
              />
              <h2 style={{ fontSize: "15px", fontWeight: 700, color: "#212529", margin: 0 }}>
                Mode de paiement
              </h2>
            </div>
            <div style={{ padding: "20px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              {MODES_PAIEMENT.map((mode) => (
                <button
                  key={mode.id}
                  onClick={() => setModePaiement(mode.id)}
                  style={{
                    display: "flex", alignItems: "center", gap: "12px",
                    padding: "14px 16px", borderRadius: "10px", cursor: "pointer",
                    border: modePaiement === mode.id ? `2px solid ${couleur}` : "1.5px solid #e9ecef",
                    background: modePaiement === mode.id ? "#EEF2FF" : "white",
                    textAlign: "left", fontFamily: "inherit", transition: "all 0.15s",
                  }}
                >
                  <img
                    src={mode.image}
                    alt={mode.label}
                    style={{ width: "40px", height: "40px", borderRadius: "8px", objectFit: "cover", flexShrink: 0 }}
                  />
                  <div>
                    <p style={{ fontSize: "13px", fontWeight: 600, color: modePaiement === mode.id ? couleur : "#212529", margin: "0 0 2px" }}>
                      {mode.label}
                    </p>
                    <p style={{ fontSize: "11px", color: "#868E96", margin: 0 }}>
                      {mode.description}
                    </p>
                  </div>
                  {modePaiement === mode.id && (
                    <div style={{ marginLeft: "auto", width: "18px", height: "18px", background: couleur, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                      <span style={{ color: "white", fontSize: "11px", fontWeight: 700 }}>✓</span>
                    </div>
                  )}
                </button>
              ))}
            </div>

            {/* Champs carte Visa */}
            {modePaiement === "visa" && (
              <div style={{ padding: "0 20px 20px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
                <div style={{ gridColumn: "1 / -1" }}>
                  <label style={{ fontSize: "12px", fontWeight: 600, color: "#495057", display: "block", marginBottom: "6px" }}>
                    Numéro de carte
                  </label>
                  <input
                    placeholder="1234 5678 9012 3456"
                    style={{ width: "100%", padding: "9px 12px", borderRadius: "8px", border: "0.5px solid #dee2e6", fontSize: "13px", outline: "none", fontFamily: "inherit", boxSizing: "border-box" }}
                    onFocus={e => e.target.style.borderColor = couleur}
                    onBlur={e => e.target.style.borderColor = "#dee2e6"}
                  />
                </div>
                <div>
                  <label style={{ fontSize: "12px", fontWeight: 600, color: "#495057", display: "block", marginBottom: "6px" }}>
                    Date d'expiration
                  </label>
                  <input
                    placeholder="MM/AA"
                    style={{ width: "100%", padding: "9px 12px", borderRadius: "8px", border: "0.5px solid #dee2e6", fontSize: "13px", outline: "none", fontFamily: "inherit", boxSizing: "border-box" }}
                    onFocus={e => e.target.style.borderColor = couleur}
                    onBlur={e => e.target.style.borderColor = "#dee2e6"}
                  />
                </div>
                <div>
                  <label style={{ fontSize: "12px", fontWeight: 600, color: "#495057", display: "block", marginBottom: "6px" }}>
                    CVV
                  </label>
                  <input
                    placeholder="123"
                    type="password"
                    style={{ width: "100%", padding: "9px 12px", borderRadius: "8px", border: "0.5px solid #dee2e6", fontSize: "13px", outline: "none", fontFamily: "inherit", boxSizing: "border-box" }}
                    onFocus={e => e.target.style.borderColor = couleur}
                    onBlur={e => e.target.style.borderColor = "#dee2e6"}
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        {/* ── COLONNE DROITE : RÉCAPITULATIF ── */}
        <div style={{ background: "white", borderRadius: "14px", border: "0.5px solid #e9ecef", overflow: "hidden", position: "sticky", top: "80px" }}>

          {/* Header bleu avec articles */}
          <div style={{ background: `linear-gradient(135deg, ${couleur}, #4C6EF5)`, padding: "20px" }}>
            <h2 style={{ color: "white", fontSize: "16px", fontWeight: 700, margin: "0 0 16px" }}>
              Récapitulatif
            </h2>
            {panier.map((a) => (
              <div key={a.id} style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "10px" }}>
                <div style={{ width: "40px", height: "40px", background: "white", borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <img src={a.image} alt={a.title} style={{ maxWidth: "34px", maxHeight: "34px", objectFit: "contain" }} />
                </div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontSize: "12px", color: "rgba(255,255,255,0.9)", margin: "0 0 2px", fontWeight: 500 }}>
                    {a.title?.slice(0, 28)}...
                  </p>
                  <p style={{ fontSize: "11px", color: "rgba(255,255,255,0.65)", margin: 0 }}>
                    {a.price} € × {a.quantite}
                  </p>
                </div>
                <span style={{ fontSize: "13px", fontWeight: 700, color: "white" }}>
                  {(a.price * a.quantite).toFixed(2)} €
                </span>
              </div>
            ))}
          </div>

          {/* Corps */}
          <div style={{ padding: "20px", display: "flex", flexDirection: "column", gap: "12px" }}>

            {/* Image livraison */}
            <div style={{ borderRadius: "10px", overflow: "hidden", height: "90px" }}>
              <img
                src="https://images.unsplash.com/photo-1566576721346-d4a3b4eaeb55?w=400&q=80"
                alt="livraison"
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
            </div>

            {/* Sous-total */}
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: "13px", color: "#868E96" }}>
              <span>Sous-total</span>
              <span>{totalPrix.toFixed(2)} €</span>
            </div>

            {/* Livraison */}
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: "13px", color: "#868E96" }}>
              <span>Livraison</span>
              <span style={{ color: fraisLivraison === 0 ? "#0CA678" : "#868E96", fontWeight: fraisLivraison === 0 ? 700 : 400 }}>
                {fraisLivraison === 0 ? "Gratuite 🎉" : `${fraisLivraison.toFixed(2)} €`}
              </span>
            </div>

            {/* Alerte livraison gratuite */}
            {fraisLivraison > 0 && (
              <div style={{ background: "#FFF9DB", borderRadius: "8px", padding: "10px 12px", display: "flex", alignItems: "center", gap: "8px" }}>
                <img
                  src="https://images.unsplash.com/photo-1526367790999-0150786686a2?w=40&q=80"
                  alt=""
                  style={{ width: "28px", height: "28px", borderRadius: "6px", objectFit: "cover" }}
                />
                <span style={{ fontSize: "11px", color: "#F08C00", fontWeight: 500 }}>
                  Ajoutez {(500 - totalPrix).toFixed(2)} € pour la livraison gratuite
                </span>
              </div>
            )}

            <div style={{ height: "0.5px", background: "#e9ecef" }} />

            {/* Total */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: "#EEF2FF", borderRadius: "10px", padding: "14px 16px" }}>
              <span style={{ fontSize: "15px", fontWeight: 700, color: "#212529" }}>Total</span>
              <span style={{ fontSize: "22px", fontWeight: 700, color: couleur }}>
                {totalFinal.toFixed(2)} €
              </span>
            </div>

            {/* Mode paiement sélectionné */}
            <div style={{ display: "flex", alignItems: "center", gap: "10px", background: "#f8f9fa", borderRadius: "8px", padding: "10px 12px" }}>
              <img
                src={MODES_PAIEMENT.find(m => m.id === modePaiement)?.image}
                alt=""
                style={{ width: "32px", height: "32px", borderRadius: "6px", objectFit: "cover" }}
              />
              <div>
                <p style={{ fontSize: "11px", color: "#868E96", margin: "0 0 2px" }}>Mode de paiement</p>
                <p style={{ fontSize: "12px", fontWeight: 600, color: couleur, margin: 0 }}>
                  {MODES_PAIEMENT.find(m => m.id === modePaiement)?.label}
                </p>
              </div>
            </div>

            {/* ── BOUTON CONFIRMER BLEU ── */}
            <button
              onClick={confirmerCommande}
              style={{
                background: `linear-gradient(135deg, ${couleur} 0%, #4C6EF5 100%)`,
                color: "white",
                border: "none",
                borderRadius: "10px",
                padding: "16px",
                fontSize: "15px",
                fontWeight: 700,
                cursor: "pointer",
                width: "100%",
                fontFamily: "inherit",
                boxShadow: "0 6px 20px rgba(59,91,219,0.35)",
                letterSpacing: "0.3px",
              }}
              onMouseEnter={e => e.currentTarget.style.boxShadow = "0 8px 24px rgba(59,91,219,0.5)"}
              onMouseLeave={e => e.currentTarget.style.boxShadow = "0 6px 20px rgba(59,91,219,0.35)"}
            >
              Confirmer la commande →
            </button>

            <Link to="/catalogue" style={{ textAlign: "center", fontSize: "13px", color: "#868E96", display: "block" }}>
              ← Continuer mes achats
            </Link>

            {/* Badge sécurité */}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "8px" }}>
              <img
                src="https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=30&q=80"
                alt="sécurisé"
                style={{ width: "24px", height: "24px", borderRadius: "4px", objectFit: "cover" }}
              />
              <span style={{ fontSize: "11px", color: "#adb5bd" }}>Paiement 100% sécurisé</span>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}
